//! Effective variance (second central moment) of craft-blur's actual impulse responses against
//! the exact values generated by the Lean model in `../lean` (`vectors/lean-blur.csv`).
//! Ticket cloudbring/artcraft-algorithms#215 (Lean) and #203 (measurement).
//!
//! 1-D: `filter_rows` on a single row. 2-D: `apply` on a square plane, with the variance taken
//! along each axis separately (the separable response has marginals of `sigma_eff^2` on both).

use craft_blur::{Cancel, Edge, Error, Gaussian, Quality, Scratch, Separable, Shape, box_widths};

struct Row {
    kernel: String,
    sigma: f32,
    widths: Vec<usize>,
    accepted: bool,
    var_rat: Option<(i128, i128)>,
    var: f64,
    dc: f64,
}

fn fraction(text: &str) -> Result<(i128, i128), Box<dyn std::error::Error>> {
    let (n, d) = text.split_once('/').ok_or("missing '/'")?;
    Ok((n.parse()?, d.parse()?))
}

fn rows() -> Result<Vec<Row>, Box<dyn std::error::Error>> {
    let table = include_str!("vectors/lean-blur.csv");
    let mut lines = table.lines();
    assert_eq!(lines.next(), Some("kernel,sigma,widths,accepted,var_rat,var_dec,dc_dec"));
    let mut out = Vec::new();
    for line in lines {
        let f: Vec<&str> = line.split(',').collect();
        assert_eq!(f.len(), 7, "{line}");
        let (n, d) = fraction(f[1])?;
        let sigma = (n as f64 / d as f64) as f32;
        assert_eq!(f64::from(sigma), n as f64 / d as f64, "sigma {} is not exact in f32", f[1]);
        out.push(Row {
            kernel: f[0].to_string(),
            sigma,
            widths: f[2].split_whitespace().map(str::parse).collect::<Result<_, _>>()?,
            accepted: f[3] == "true",
            var_rat: if f[4].is_empty() { None } else { Some(fraction(f[4])?) },
            var: f[5].parse()?,
            dc: f[6].parse()?,
        });
    }
    Ok(out)
}

fn variance(values: &[f32]) -> (f64, f64) {
    let centre = (values.len() / 2) as f64;
    let mass: f64 = values.iter().map(|v| f64::from(*v)).sum();
    let mean = values.iter().enumerate().map(|(i, v)| f64::from(*v) * (i as f64 - centre)).sum::<f64>() / mass;
    let second = values.iter().enumerate().map(|(i, v)| f64::from(*v) * (i as f64 - centre).powi(2)).sum::<f64>() / mass;
    (second - mean * mean, mass)
}

fn half(sigma: f32, factor: f32) -> usize {
    (factor * sigma).ceil().max(8.0) as usize + 8
}

fn impulse_1d(gaussian: &Gaussian, sigma: f32) -> Result<Vec<f32>, Error> {
    let n = 2 * half(sigma, 24.0) + 1;
    let mut line = vec![0.0; n];
    line[n / 2] = 1.0;
    gaussian.filter_rows(&mut line, Shape::new(n, 1, 1)?, Edge::Clamp, &mut Scratch::default(), Cancel::Never)?;
    Ok(line)
}

/// Marginal variances `(x, y)`, mass and the covariance of a separable 2-D impulse response.
fn impulse_2d(gaussian: &Gaussian, sigma: f32, factor: f32) -> Result<(f64, f64, f64, f64), Error> {
    let n = 2 * half(sigma, factor) + 1;
    let mut plane = vec![0.0; n * n];
    plane[(n / 2) * n + n / 2] = 1.0;
    gaussian.apply(&mut plane, Shape::new(n, n, 1)?, Edge::Clamp, &mut Scratch::default(), Cancel::Never)?;
    let mut columns = vec![0.0_f32; n];
    let mut rows = vec![0.0_f32; n];
    let (mut covariance, mut mass) = (0.0_f64, 0.0_f64);
    let c = (n / 2) as f64;
    for (y, row) in plane.chunks_exact(n).enumerate() {
        for (x, v) in row.iter().enumerate() {
            columns[x] += *v;
            rows[y] += *v;
            covariance += f64::from(*v) * (x as f64 - c) * (y as f64 - c);
            mass += f64::from(*v);
        }
    }
    Ok((variance(&columns).0, variance(&rows).0, covariance / mass, mass))
}

fn quality(row: &Row) -> Option<Quality> {
    match row.kernel.as_str() {
        "sampled" => Some(Quality::Exact),
        "yvv" => Some(Quality::RecursiveRaw),
        "box3" => Some(Quality::BoxApprox { passes: 3 }),
        other => panic!("unknown kernel {other}"),
    }
}

/// Relative tolerance on the variance. Observed worst case is about 2e-8 for every kernel
/// (f32 output rounding; for the recursive filter also f64 coefficients and window truncation),
/// so 1e-6 leaves a margin of about 50x.
fn tolerance(_kernel: &str) -> f64 {
    1e-6
}

#[test]
fn csv_is_well_formed_and_covers_every_config() -> Result<(), Box<dyn std::error::Error>> {
    let rows = rows()?;
    for kernel in ["sampled", "yvv", "box3"] {
        let count = rows.iter().filter(|r| r.kernel == kernel).count();
        assert!(count >= if kernel == "yvv" { 10 } else { 15 }, "{kernel}: {count} rows");
    }
    assert!(rows.iter().all(|r| r.var > 0.0 || (r.kernel == "box3" && !r.accepted)));
    assert!(rows.iter().filter(|r| r.kernel != "box3").all(|r| (r.dc - 1.0).abs() < 1e-3 || r.kernel == "sampled"));
    Ok(())
}

#[test]
fn box_widths_and_acceptance_match_lean() -> Result<(), Box<dyn std::error::Error>> {
    let mut accepted = 0;
    for row in rows()?.iter().filter(|r| r.kernel == "box3") {
        assert_eq!(box_widths(row.sigma)?.to_vec(), row.widths, "sigma={}", row.sigma);
        let result = Gaussian::new(row.sigma, Quality::BoxApprox { passes: 3 });
        if row.accepted {
            accepted += 1;
            let gaussian = result?;
            assert_eq!(gaussian.separable(), &Separable::Boxes([row.widths[0], row.widths[1], row.widths[2]]));
        } else {
            assert!(matches!(result, Err(Error::BoxTolerance { .. })), "sigma={}: {result:?}", row.sigma);
        }
    }
    assert!(accepted >= 6, "{accepted}");
    Ok(())
}

#[test]
fn one_dimensional_effective_variance_matches_lean() -> Result<(), Box<dyn std::error::Error>> {
    let mut worst = [0.0_f64; 3];
    for row in rows()? {
        let Some(quality) = quality(&row) else { continue };
        if row.kernel == "box3" && !row.accepted {
            continue;
        }
        let gaussian = Gaussian::new(row.sigma, quality)?;
        let (measured, mass) = variance(&impulse_1d(&gaussian, row.sigma)?);
        let relative = (measured / row.var - 1.0).abs();
        let slot = ["sampled", "yvv", "box3"].iter().position(|k| *k == row.kernel).unwrap_or(0);
        worst[slot] = worst[slot].max(relative);
        assert!(relative <= tolerance(&row.kernel), "{} sigma={}: measured {measured} vs Lean {} (rel {relative:e})", row.kernel, row.sigma, row.var);
        assert!((mass - 1.0).abs() < 1e-5 && (mass - row.dc).abs() < 1e-3, "{} sigma={}: mass {mass}", row.kernel, row.sigma);
        if let Some((n, d)) = row.var_rat {
            assert!((n as f64 / d as f64 - row.var).abs() <= 1e-12 * row.var.max(1.0), "decimal and fraction disagree");
        }
    }
    println!("worst relative error against Lean (sampled, yvv, box3): {worst:?}");
    Ok(())
}

#[test]
fn recursive_quality_uses_yvv_from_sigma_eight() -> Result<(), Box<dyn std::error::Error>> {
    for row in rows()?.iter().filter(|r| r.kernel == "yvv" && r.sigma >= 8.0) {
        let gaussian = Gaussian::new(row.sigma, Quality::Recursive)?;
        assert!(matches!(gaussian.separable(), Separable::Recursive(_)));
        let (measured, _) = variance(&impulse_1d(&gaussian, row.sigma)?);
        assert!((measured / row.var - 1.0).abs() <= tolerance("yvv"), "sigma={}", row.sigma);
    }
    Ok(())
}

#[test]
fn separable_two_dimensional_variance_matches_lean() -> Result<(), Box<dyn std::error::Error>> {
    for row in rows()? {
        let Some(quality) = quality(&row) else { continue };
        if row.kernel == "box3" && !row.accepted {
            continue;
        }
        let gaussian = Gaussian::new(row.sigma, quality)?;
        // Finite kernels reach at most ~3 sigma + 3 per axis; the recursive tail needs a wide window.
        let (x, y, covariance, mass) = impulse_2d(&gaussian, row.sigma, if row.kernel == "yvv" { 14.0 } else { 5.0 })?;
        let tol = tolerance(&row.kernel) * 5.0;
        for (axis, v) in [("x", x), ("y", y)] {
            assert!((v / row.var - 1.0).abs() <= tol, "{} sigma={} axis {axis}: {v} vs Lean {}", row.kernel, row.sigma, row.var);
        }
        assert!(covariance.abs() <= 1e-4 * row.var, "{} sigma={}: covariance {covariance}", row.kernel, row.sigma);
        assert!((mass - 1.0).abs() < 1e-4, "{} sigma={}: mass {mass}", row.kernel, row.sigma);
    }
    Ok(())
}
